import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-faculty',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:24px;">
      <h1 style="font-size:24px;font-weight:700;">Faculty</h1>
      <button class="btn btn-primary">+ Add Faculty</button>
    </div>
    <div class="card"><table><thead><tr><th>Name</th><th>Subject</th><th>Students</th><th>Rating</th><th>Status</th></tr></thead><tbody>
      <tr *ngFor="let f of faculty"><td>{{f.name}}</td><td>{{f.subject}}</td><td>{{f.students}}</td><td>⭐ {{f.rating}}</td><td><span class="badge badge-success">Active</span></td></tr>
    </tbody></table></div>
  `
})
export class FacultyComponent {
  faculty = [
    { name: 'Dr. Raj Kumar', subject: 'Core Java', students: 150, rating: 4.8 },
    { name: 'Prof. Priya Sharma', subject: 'Spring Boot', students: 120, rating: 4.7 },
    { name: 'Mr. Arun Gupta', subject: 'Aptitude', students: 200, rating: 4.5 },
  ];
}
